#pragma once
#include "topology.hpp"
#include <sstream>
inline void save_checkpoint(HNSW& g,Fvecs& base,const fs::path& p,double elapsed){auto tmp=p;tmp+=".tmp";Gzip z(tmp,true);std::ostringstream rng,update;rng<<g.level_generator_;update<<g.update_probability_generator_;json meta={{"version",1},{"base_n",base.n},{"d",base.d},{"count",g.cur_element_count.load()},{"maxlevel",g.maxlevel_},{"entry",g.enterpoint_node_},{"M",g.M_},{"efc",g.ef_construction_},{"rng",rng.str()},{"update_rng",update.str()},{"elapsed",elapsed}};std::string text=meta.dump();uint32_t length=text.size();z.value(length);z.bytes(text.data(),length);
 for(size_t i=0;i<g.cur_element_count;++i){uint64_t label=g.getExternalLabel(i);uint32_t lev=g.element_levels_[i];z.value(label);z.value(lev);for(uint32_t l=0;l<=lev;++l){auto a=g.get_linklist_at_level(i,l);uint32_t count=g.getListCount(a);z.value(count);z.bytes(a+1,count*4);}}z.close();fs::rename(tmp,p);}
inline std::pair<std::unique_ptr<HNSW>,double> load_checkpoint(const fs::path& p,Fvecs& base,hnswlib::SpaceInterface<float>* space){Gzip z(p,false);uint32_t length;z.value(length);require(length<65536,"checkpoint header size");std::string text(length,'\0');z.bytes(text.data(),length);auto c=json::parse(text);require(c["version"]==1&&c["base_n"]==base.n&&c["d"]==base.d&&c["M"]==32&&c["efc"]==200,"checkpoint metadata");size_t count=c["count"];require(count>0&&count<=base.n,"checkpoint count");auto g=std::make_unique<HNSW>(space,base.n,32,200,20260828);g->label_lookup_.reserve(base.n);
 for(size_t i=0;i<count;++i){uint64_t label;uint32_t lev;z.value(label);z.value(lev);require(label<count&&lev<=c["maxlevel"].get<uint32_t>(),"checkpoint label/level");g->element_levels_[i]=lev;std::memset(g->data_level0_memory_+i*g->size_data_per_element_,0,g->size_data_per_element_);g->setExternalLabel(i,label);std::memcpy(g->getDataByInternalId(i),base.row(label),base.d*4);require(g->label_lookup_.emplace(label,i).second,"checkpoint duplicate label");g->linkLists_[i]=nullptr;if(lev){g->linkLists_[i]=(char*)calloc(1,lev*g->size_links_per_element_+1);require(g->linkLists_[i],"checkpoint upper allocation");}for(uint32_t l=0;l<=lev;++l){uint32_t n;z.value(n);require(n<=(l?g->maxM_:g->maxM0_),"checkpoint degree");auto a=g->get_linklist_at_level(i,l);g->setListCount(a,n);z.bytes(a+1,n*4);for(uint32_t j=0;j<n;++j)require(a[j+1]<count,"checkpoint neighbor range");}g->cur_element_count=i+1;}
 g->maxlevel_=c["maxlevel"];g->enterpoint_node_=c["entry"];std::istringstream r(c["rng"].get<std::string>()),u(c["update_rng"].get<std::string>());r>>g->level_generator_;u>>g->update_probability_generator_;require(bool(r)&&bool(u),"checkpoint random state");char trailing;require(gzread(z.f,&trailing,1)==0,"checkpoint trailing bytes");z.close();return {std::move(g),c["elapsed"].get<double>()};}
